def check_expression(expression):
    # Define a dictionary to hold matching pairs of parentheses
    matching_parentheses = {')': '(', '}': '{', ']': '['}
    # Initialize an empty stack to keep track of opening parentheses
    stack = []

    # Iterate through each character in the expression
    for char in expression:
        # If the character is an opening parenthesis, push it onto the stack
        if char in matching_parentheses.values():
            stack.append(char)
        # If the character is a closing parenthesis
        elif char in matching_parentheses:
            # If the stack is empty or the top of the stack doesn't match the corresponding opening parenthesis, return False
            if not stack or stack.pop() != matching_parentheses[char]:
                return False

    # If the stack is empty, all parentheses were matched correctly; otherwise, return False
    return not stack

